const express = require('express');
const Pool = require('pg-pool');

const app = express();
app.use(express.json());

const tenantPools = new Map();

function getOrCreateTenantPool(tenantId) {
  if (!tenantPools.has(tenantId)) {
    tenantPools.set(
      tenantId,
      new Pool({
        connectionString: `postgresql://app_user:${process.env.DB_PASS}@db.internal:5432/tenant_${tenantId}`
      })
    );
  }
  return tenantPools.get(tenantId);
}

app.get('/api/reports/financial-summary', async (req, res) => {
  if (!req.user || !req.user.tenantId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const requestedTenantId = req.headers['x-tenant-id'];

  // Enforce that caller can only query the connection pool of their authenticated tenant
  if (requestedTenantId && requestedTenantId !== req.user.tenantId) {
    return res.status(403).json({ error: 'Access denied: cannot access database pool of another tenant' });
  }

  const activeTenantId = req.user.tenantId;
  const pool = getOrCreateTenantPool(activeTenantId);

  try {
    const result = await pool.query('SELECT * FROM revenue_ledger ORDER BY recorded_at DESC LIMIT 50');
    res.json({ tenantId: activeTenantId, records: result.rows });
  } catch (err) {
    res.status(500).json({ error: 'Database query failed' });
  }
});

app.listen(9101);
